try {
  var durl = '';
  try { if (typeof MY_URL !== 'undefined' && MY_URL) durl = String(MY_URL); } catch (e) {}
  var nm = String(durl).match(/\/detail\/(\d+)\//);
  var nid = nm ? nm[1] : String(durl).replace(/[^0-9]/g, '');
