  try { return $().lazyRule(playFn, arg); } catch (e) { return 'toast://解析失败'; }
}

var items = [];
try {
  var cls = '';
  var pg = 1;
  try { if (typeof MY_URL !== 'undefined' && MY_URL) { var pp = String(MY_URL).split('##'); if (pp.length > 1 && pp[1] && pp[1] !== 'fyclass') cls = pp[1]; } } catch (e) {}
  try { if (typeof MY_PAGE !== 'undefined' && MY_PAGE) pg = parseInt(MY_PAGE) || 1; } catch (e) {}
  if (cls && ['Editor-Choice','girl-dom','ntr','sm-ai-dramer','Xianxia','Humiliation','story','Historical','lesbian','Home','Fantasy','outdoor','dark-content','school','Workplace','exposure-exhibitionism'].indexOf(cls) < 0) cls = '';
  if (!cls) {
    var path = pg <= 1 ? '/' : '/?page=' + pg;
    var html = jGet(SITE + path);
    if (pg <= 1) {
      var fi = html.indexOf('featured-section');
      var gi = html.indexOf('drama-grid');
      if (fi >= 0 && gi > fi) {
        var feat = jCards(html.slice(fi, gi));
        if (feat.length) {
          items.push({title: '近期佳作推荐', col_type: 'text_1', url: 'hiker://empty'});
          for (var f = 0; f < feat.length; f++) items.push(feat[f]);
        }
        var grid = jCards(html.slice(gi));
        if (grid.length) {
          items.push({title: '全部短剧', col_type: 'text_1', url: 'hiker://empty'});
          for (var g2 = 0; g2 < grid.length; g2++) items.push(grid[g2]);
        }
      }
      if (!items.length) items = jCards(html);
    } else {
      items = jCards(html);
    }
  } else {
    var path2 = pg <= 1 ? '/tag/' + cls : '/tag/' + cls + '?page=' + pg;
    var html2 = jGet(SITE + path2);
    items = jCards(html2);
  }
} catch (e) { items = []; }
setResult(items);

