var API = SITE + '/api/v1';
var UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36';
function jUuid() {
  var h = '0123456789abcdef';
  var s = '';
  for (var i = 0; i < 36; i++) {
    if (i === 8 || i === 13 || i === 18 || i === 23) { s += '-'; continue; }
    var r = Math.floor(Math.random() * 16);
    if (i === 14) r = 4;
    if (i === 19) r = (r & 3) | 8;
    s += h.charAt(r);
  }
  return s;
}
function jAuth() {
  try {
    var r = fetch(API + '/auth/device', {method: 'POST', headers: {'Accept': 'application/json', 'Content-Type': 'application/json'}, body: {deviceId: 'h5:' + jUuid()}});
    var o = JSON.parse(r);
    if (o && o.token) return o.token;
    return '';
  } catch (e) { return ''; }
}
function jGet(url, token) {
  try {
    var h = {'Accept': 'application/json', 'User-Agent': UA};
    if (token) h.Authorization = 'Bearer ' + token;
    return fetch(url, {headers: h});
  } catch (e) { return ''; }
}
function jFix(u) {
  if (!u) return '';
  u = String(u).replace(/^\s+|\s+$/g, '');
  if (u.indexOf('//') === 0) return 'https:' + u;
  if (u.indexOf('/') === 0) return SITE + u;
  return u;
}
function jDesc(d) {
  var t = '';
  if (d && d.tags && d.tags.length) t = d.tags.slice(0, 2).join(' · ');
  var n = d ? (d.episodeCount || 0) : 0;
  var c = n ? ('全' + n + '集') : '';
  if (t && c) return t + ' ' + c;
  return t || c;
}
function jCards(list, pg) {
  var out = [];
  var arr = list || [];
  var start = (pg - 1) * 24;
  var end = start + 24;
  for (var i = start; i < end && i < arr.length; i++) {
    var d = arr[i];
    if (!d || !d.id || !d.title) continue;
    out.push({title: d.title, img: jFix(d.coverUrl), desc: jDesc(d), url: SITE + '/drama/' + d.id});
  }
  return out;
}
function playFn(arg) {
  var SITE = 'https://play.jinguoduanju.app';
  var API = SITE + '/api/v1';
  var UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36';
  function uuid() {
    var h = '0123456789abcdef';
    var s = '';
    for (var i = 0; i < 36; i++) {
      if (i === 8 || i === 13 || i === 18 || i === 23) { s += '-'; continue; }
      var r = Math.floor(Math.random() * 16);
      if (i === 14) r = 4;
      if (i === 19) r = (r & 3) | 8;
      s += h.charAt(r);
    }
    return s;
  }
  function auth() {
    try {
      var r = fetch(API + '/auth/device', {method: 'POST', headers: {'Accept': 'application/json', 'Content-Type': 'application/json'}, body: {deviceId: 'h5:' + uuid()}});
      var o = JSON.parse(r);
      if (o && o.token) return o.token;
      return '';
    } catch (e) { return ''; }
  }
  function g(u, token) {
    try {
      var h = {'Accept': 'application/json', 'User-Agent': UA};
      if (token) h.Authorization = 'Bearer ' + token;
      return fetch(u, {headers: h});
    } catch (e) { return ''; }
  }
  var ep = String(arg).replace(/[^0-9]/g, '');
  if (!ep) return 'toast://解析失败';
  var token = auth();
  if (!token) return 'toast://解析失败';
  var acc = g(API + '/me/episodes/' + ep + '/access', token);
  if (!acc) return 'toast://解析失败';
  var ao = null;
  try { ao = JSON.parse(acc); } catch (e) { return 'toast://解析失败'; }
  if (!ao || ao.allowed !== true) return 'toast://解析失败';
  var pl = g(API + '/episodes/' + ep + '/play', token);
  if (!pl) return 'toast://解析失败';
  var po = null;
  try { po = JSON.parse(pl); } catch (e) { return 'toast://解析失败'; }
  if (!po || !po.videoUrl || String(po.videoUrl).indexOf('http') !== 0) return 'toast://解析失败';
  return po.videoUrl;
}
function toPlay(arg) {
  try { return $().lazyRule(playFn, arg); } catch (e) { return 'toast://解析失败'; }
}

var items = [];
try {
  var kw = '';
  var pg = 1;
  try { if (typeof MY_KEYWORD !== 'undefined' && MY_KEYWORD) kw = String(MY_KEYWORD); } catch (e) {}
  try { if (typeof MY_PAGE !== 'undefined' && MY_PAGE) pg = parseInt(MY_PAGE) || 1; } catch (e) {}
  if (kw) {
    var txt = jGet(API + '/dramas?sort=latest&q=' + encodeURIComponent(kw), '');
    var list = [];
    try { list = JSON.parse(txt); } catch (e) { list = []; }
    if (!list || typeof list.length === 'undefined') list = [];
    items = jCards(list, pg).slice(0, 40);
  }
} catch (e) { items = []; }
setResult(items);

