var SITE = 'https://yxql-imh-nh4d.taoquan26s111.cc';
var HOME = SITE + '/oaoaoa/';
var JINA = 'https://r.jina.ai/';
var UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36';
function jGet(url) {
  try { return fetch(url, {headers: {'User-Agent': UA, 'Referer': SITE + '/', 'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'}}); } catch (e) { return ''; }
}
function jGetJina(url) {
  try { return fetch(JINA + url, {headers: {'User-Agent': UA, 'Referer': SITE + '/', 'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8', 'X-Return-Format': 'html'}}); } catch (e) { return ''; }
}
function jUnesc(s) {
  if (!s) return '';
  return s.replace(/\\\//g, '/').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#(\d+);/g, function (m, d) { return String.fromCharCode(parseInt(d, 10)); }).replace(/&#x([0-9a-fA-F]+);/g, function (m, h) { return String.fromCharCode(parseInt(h, 16)); });
}
function jStrip(s) {
  if (!s) return '';
  var t = String(s).replace(/<[^>]+>/g, ' ');
  t = jUnesc(t);
  return t.replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, '');
}
function jFix(u) {
  if (!u) return '';
  u = String(u).replace(/^\s+|\s+$/g, '');
  if (u.indexOf('//') === 0) return 'https:' + u;
  if (u.indexOf('/') === 0) return SITE + u;
  return u;
}
function jCards(html) {
  var out = [];
  var seen = {};
  var pat = /<a class="stui-vodlist__thumb[^>]*href="\/vodplay\/(\d+)-1-1\/"[^>]*title="([^"]*)"[^>]*data-original="([^"]*)"/g;
  var m;
  while ((m = pat.exec(String(html || ''))) !== null) {
    var vid = m[1];
    if (seen[vid]) continue;
    seen[vid] = 1;
    var title = jUnesc(m[2]).replace(/^\s+|\s+$/g, '');
    if (!title) continue;
    out.push({title: title, img: jFix(m[3]), desc: '', url: SITE + '/voddetail/' + vid + '/'});
  }
  return out;
}

