  function g(u) { try { return fetch(u, {headers: {'User-Agent': UA, 'Referer': SITE + '/', 'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'}}); } catch (e) { return ''; } }
  function gj(u) { try { return fetch(JINA + u, {headers: {'User-Agent': UA, 'Referer': SITE + '/', 'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8', 'X-Return-Format': 'html'}}); } catch (e) { return ''; } }
  function un(s) { if (!s) return ''; return s.replace(/\\\//g, '/').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#(\d+);/g, function (m, d) { return String.fromCharCode(parseInt(d, 10)); }).replace(/&#x([0-9a-fA-F]+);/g, function (m, h) { return String.fromCharCode(parseInt(h, 16)); }); }
  var p = String(arg).split('|');
  if (p.length < 2) return 'toast://解析失败';
  var nid = p[0].replace(/[^0-9]/g, '');
  var ep = p[1].replace(/[^0-9]/g, '') || '1';
  if (!nid) return 'toast://解析失败';
  var playUrl = SITE + '/vodplay/' + nid + '-1-' + ep + '/';
  var html = g(playUrl);
  if (!html || html.indexOf('player_aaaa') < 0) html = gj(playUrl);
  if (!html) return 'toast://解析失败';
  var m = html.match(/player_aaaa=[\s\S]*?"url":"([^"]+)"/);
  if (!m) return 'toast://解析失败';
  var u = un(m[1]);
  if (!u || u.indexOf('http') !== 0) return 'toast://解析失败';
  return u;
}
function toPlay(arg) {
  try { return $().lazyRule(playFn, arg); } catch (e) { return 'toast://解析失败'; }
}

