function jGet(url, nocache) {
  var h = {'User-Agent': UA, 'Referer': SITE + '/', 'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8', 'X-Return-Format': 'html'};
  if (nocache) h['X-No-Cache'] = 'true';
  try { return fetch(url, {headers: h}); } catch (e) { return ''; }
}
function jUnesc(s) {
  if (!s) return '';
  return s.replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#(\d+);/g, function (m, d) { return String.fromCharCode(parseInt(d, 10)); }).replace(/&#x([0-9a-fA-F]+);/g, function (m, h) { return String.fromCharCode(parseInt(h, 16)); });
}
function jCards(html) {
  var out = [];
  if (!html || typeof html !== 'string') return out;
  var starts = [];
  var re = /<div class="(?:mgn-item|mg-item mg-card)"/g;
  var m;
  while ((m = re.exec(html)) !== null) starts.push(m.index);
  for (var i = 0; i < starts.length; i++) {
    var b = html.substring(starts[i], i + 1 < starts.length ? starts[i + 1] : starts[i] + 5000);
    var a = b.match(/<a href="(\/movie\/detail\/([a-f0-9\-]+)\.html)"[^>]*title="([^"]*)"/);
    if (!a) continue;
    var im = b.match(/<img[^>]+src="([^"]+)"/);
    if (!im) im = b.match(/<img[^>]+data-src="([^"]+)"/);
    var pic = im ? im[1] : '';
    if (pic.indexOf('//') === 0) pic = 'https:' + pic;
    else if (pic.indexOf('/') === 0) pic = SITE + pic;
    var rem = '';
    var y = b.match(/mg[n]?-badge--?year[^>]*>([^<]+)/);
    if (y) rem = jUnesc(y[1]).trim();
    var tg = b.match(/mg[n]?-badge--?subtitle[^>]*>([^<]+)/);
    if (tg) rem = (rem ? rem + ' ' : '') + jUnesc(tg[1]).trim();
    var acts = [];
    var ar = /mg[n]?-actress[^>]*>\s*<a[^>]*>([^<]+)/g;
    var am;
    while ((am = ar.exec(b)) !== null && acts.length < 8) acts.push(jUnesc(am[1]).trim());
    if (acts.length) rem = (rem ? rem + ' ' : '') + acts.join(',');
    out.push({title: jUnesc(a[3]).trim(), img: pic, desc: rem, url: SITE + a[1]});
  }
  return out;
}
function jActorCards(html) {
  var out = [];
  if (!html || typeof html !== 'string') return out;
