}

function playFn(durl) {

      var SITE2 = 'https://www.javrate.com';
      var JINA2 = 'https://r.jina.ai/';
      var UA2 = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36';
      function g2(url, nocache) {
        var h = {'User-Agent': UA2, 'Referer': SITE2 + '/', 'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8', 'X-Return-Format': 'html'};
        if (nocache) h['X-No-Cache'] = 'true';
        try { return fetch(url, {headers: h}); } catch (e) { return 'toast://解析失败'; }
      }
      function g2m(url) {
        try { return fetch(url, {headers: {'User-Agent': UA2, 'Referer': SITE2 + '/'}}); } catch (e) { return 'toast://解析失败'; }
      }
      function abs2(base, rel) {
        if (rel.indexOf('http') === 0) return rel;
        var o = base.match(/^(https?:\/\/[^\/]+)/);
        if (rel.indexOf('/') === 0) return (o ? o[1] : '') + rel;
        return base.substring(0, base.lastIndexOf('/') + 1) + rel;
      }
      function unesc2(s) { return s ? s.replace(/\\\//g, '/').replace(/&amp;/g, '&') : ''; }
      try {
        var html = g2(JINA2 + durl, true);
        if (!html) return 'toast://解析失败';
        var cands = [];
        var pats = [/id="v2-player"[^>]*src="([^"]+)"/, /<iframe[^>]+src="(\/[Pp]layer[^"]*)"/, /"embedUrl":\s*"([^"]+)"/];
        for (var pi = 0; pi < pats.length; pi++) {
          var pm = html.match(pats[pi]);
          if (pm) cands.push(unesc2(pm[1]));
        }
        var src = '';
        for (var ci = 0; ci < cands.length && !src; ci++) {
          var emb = cands[ci];
          if (emb.indexOf('//') === 0) emb = 'https:' + emb;
          else if (emb.indexOf('http') !== 0) emb = SITE2 + emb;
          var ep = (emb.indexOf('javrate.com') >= 0) ? g2(JINA2 + emb, true) : g2(emb, true);
          if (!ep) continue;
          var hasM3 = ep.indexOf('m3u8') >= 0 || ep.indexOf('signedUrl') >= 0 || ep.indexOf('var source') >= 0;
          if (!hasM3 && emb.indexOf('javrate.com') >= 0) {
            var ep2 = g2(emb, true);
            if (ep2 && (ep2.indexOf('m3u8') >= 0 || ep2.indexOf('signedUrl') >= 0 || ep2.indexOf('var source') >= 0)) ep = ep2;
          }
                    var sm2 = ep.match(/initialSignedUrl:\s*'([^']+)'/) || ep.match(/signedUrl:\s*'([^']+)'/) || ep.match(/https?:\/\/videocdn[^\s"']+m3u8[^\s"']*/) || ep.match(/https?:\/\/[^\s"']*cloud-hot[^\s"']*m3u8[^\s"']*/);
          if (sm2) { src = unesc2(sm2[1] || sm2[0]); }
          if (!src) {
            var m3 = ep.match(/var\s+source\s*=\s*"([^"]+)"/) || ep.match(/var\s+now\s*=\s*"([^"]+)"/);
            if (m3) src = unesc2(m3[1]);
          }
          if (!src) {
            var m4 = ep.match(/https?:\/\/[^\s"'\\]+?\.m3u8[^\s"'\\]*/);
            if (m4 && m4[0].indexOf('/player/') < 0 && m4[0].indexOf('/Player?') < 0) src = unesc2(m4[0]);
          }
        }
        if (!src) return 'toast://解析失败';
        if (src.indexOf('//') === 0) src = 'https:' + src;
        var q = src.indexOf('?') >= 0 ? src.substring(src.indexOf('?') + 1) : '';
        var addQ = function (u) {
          if (!q) return u;
          if (u.indexOf('?') >= 0) return u;
          return u + '?' + q;
        };
        var master = g2m(src);
        if (!master) return src;
        var lines = master.split('\n');
        var variants = [];
        for (var i = 0; i < lines.length; i++) {
          var ln = lines[i].trim();
          if (ln.indexOf('#EXT-X-STREAM-INF') === 0) {
            var bw = 0;
            var bwm = ln.match(/BANDWIDTH=(\d+)/);
            if (bwm) bw = parseInt(bwm[1], 10) || 0;
            var j = i + 1;
            while (j < lines.length && lines[j].trim() === '') j++;
            if (j < lines.length && lines[j].trim().indexOf('#') !== 0) variants.push({bw: bw, uri: lines[j].trim()});
          }
        }
        var target = '';
        if (variants.length) {
          var best = variants[0];
          for (var k = 1; k < variants.length; k++) if (variants[k].bw > best.bw) best = variants[k];
          target = addQ(abs2(src, best.uri));
        } else {
          target = src;
        }
        var pl = g2m(target);
        if (!pl) return src;
        var base2 = target.substring(0, target.lastIndexOf('/') + 1);
        var out = [];
        var pls = pl.split('\n');
        for (var p = 0; p < pls.length; p++) {
          var line = pls[p].trim();
          if (!line) { out.push(''); continue; }
          if (line.indexOf('#') === 0) {
            var km = line.match(/URI="([^"]+)"/);
            if (km) line = line.replace(km[1], addQ(abs2(base2, km[1])));
            out.push(line);
          } else {
            out.push(addQ(abs2(base2, line)));
          }
        }
        var uuid = '';
        var um = durl.match(/([a-f0-9\-]{36})\.html/);
        if (um) uuid = um[1];
        var fname = 'hiker://files/cache/jr_' + (uuid || String(Date.now())) + '.m3u8';
        try {
          saveFile(fname, out.join('\n'));
          return getPath(fname);
        } catch (e) { return target; }
      } catch (e) { return 'toast://解析失败'; }

}
